#[cfg(not(target_pointer_width = "64"))]
pub type AtomicSsize = Atomic32;

// -----------------------------------------------------------------------------------------
// Locks, condition variables and threads: `unix/pthread.h`'s `git_mutex`, `git_cond`,
// `git_rwlock` and `git_thread_*` macros, native over the standard library.
// -----------------------------------------------------------------------------------------

pub use self::sync::{
    Condvar, JoinHandle, Mutex, MutexGuard, RwLock, RwLockReadGuard, RwLockWriteGuard, spawn,
};

/// The locks, condition variables and threads of `unix/pthread.h`, native.
///
/// Each of the header's macros names a POSIX entity: `git_mutex` is `pthread_mutex_t` and
/// its four operations `pthread_mutex_init`, `_lock`, `_unlock` and `_destroy`, each with
/// default attributes; `git_cond` is `pthread_cond_t`, `git_rwlock` `pthread_rwlock_t`, and
/// `git_thread_create` and `git_thread_join` are `pthread_create` and `pthread_join` over a
/// [`Thread`]'s id. The header keeps them for the C that remains, which embeds its locks in
/// its own structs and expands the macros where it locks them; these Rust forms are not
/// linked to that C, and no lock or thread crosses between the two. So they are the
/// standard library's: a [`Mutex`] is a [`std::sync::Mutex`], an [`RwLock`] a
/// [`std::sync::RwLock`], a [`Condvar`] a [`std::sync::Condvar`] and [`spawn`] starts a
/// thread through [`std::thread::Builder::spawn`].
///
/// Where C locks a lock and unlocks it later by name, through the same macro family, Rust
/// locks it into a guard, and the guard's drop, or its `unlock`, releases it: the C rule
/// that a read lock is released with `git_rwlock_rdunlock` and a write lock with
/// `git_rwlock_wrunlock` is the guard's type. A guard is not [`Send`], so a lock is released
/// on the thread that took it, as POSIX requires of a default mutex and read-write lock.
/// The lock guards the data it holds, a `T`, where C's guards state it keeps beside it: a
/// lock of C's kind is a `Mutex<()>`.
///
/// The standard locks differ from C's in three ways, none of which libgit2's C relies on:
///
/// - They cannot fail to initialise, where `pthread_mutex_init` and its siblings may report
///   `EAGAIN` or `ENOMEM`, which libgit2 reports as an error: `new` is a `const fn`, and a
///   lock may be a `static`, as `GIT_RWLOCK_STATIC_INIT` initialises one in C.
/// - A lock is poisoned when a thread panics while holding it, a state C has no form of:
///   locking it then fails with a [`PoisonError`], which hands back the guard, so that a
///   caller that can vouch for the data may go on with it. C's lock fails only with the
///   errors POSIX lists, positive numbers, which libgit2's callers test with `< 0` and so
///   never see.
/// - Taking a lock the calling thread already holds, a read lock included, deadlocks or
///   panics, where it deadlocks or is undefined in C: `unix/pthread.h` forbids recursive
///   read locks for the Windows implementation's sake.
///
/// A thread started by [`spawn`] is owned by its [`JoinHandle`], which [`join`] consumes,
/// so it is joined once and never through a stale id, as a [`Thread`] value may be. The
/// closure's result is what `pthread_join` reads through its `status` argument: the value
/// the C thread's start routine returns. A [`Thread`] stays the C form of a thread C starts
/// into storage of its own, and a [`JoinHandle`] is never turned into one: the standard
/// library cannot join a thread by its raw id, so only C could join it.
///
/// [`join`]: JoinHandle::join
/// [`PoisonError`]: std::sync::PoisonError
/// [`Thread`]: super::Thread
mod sync {
    use core::fmt;
    use core::ops::{Deref, DerefMut};
    use std::io;
    use std::sync::{LockResult, PoisonError};

    /// A mutual-exclusion lock over a `T`: libgit2's `git_mutex`, `pthread_mutex_t` with
    /// default attributes, as a [`std::sync::Mutex`].
    ///
    /// [`new`](Self::new) initialises it, as `git_mutex_init` does, [`lock`](Self::lock)
    /// takes it into a [`MutexGuard`], as `git_mutex_lock` does, the guard's drop or
    /// [`MutexGuard::unlock`] releases it, as `git_mutex_unlock` does, and dropping it
    /// destroys it, as `git_mutex_free` does. The [module documentation](self) gives how it
    /// differs from C's.
    ///
    /// ```
    /// use libgit2_crustify::libgit2::src::util::thread::Mutex;
    ///
    /// let count = Mutex::new(0);
    /// *count.lock().unwrap() += 1;
    /// assert_eq!(*count.lock().unwrap(), 1);
    /// ```
    ///
    /// Replaces `mac::git_mutex`
    #[doc(alias = "git_mutex")]
    pub struct Mutex<T: ?Sized> {
        inner: std::sync::Mutex<T>,
    }

    /// The lock of a [`Mutex`], held until it is dropped or passed to
    /// [`unlock`](Self::unlock); it dereferences to the data the lock guards. It is not
    /// [`Send`]: the thread that took the lock releases it.
    pub struct MutexGuard<'a, T: ?Sized + 'a> {
        inner: std::sync::MutexGuard<'a, T>,
    }

    impl<T> Mutex<T> {
        /// A new, unlocked lock over `value`, as `git_mutex_init` initialises one with
        /// default attributes; it cannot fail, where `pthread_mutex_init` may.
        ///
        /// Replaces `mac::git_mutex_init`
        #[doc(alias = "git_mutex_init")]
        #[must_use]
        pub const fn new(value: T) -> Mutex<T> {
            Mutex {
                inner: std::sync::Mutex::new(value),
            }
        }
    }

    impl<T: ?Sized> Mutex<T> {
        /// Takes the lock, blocking until no other thread holds it, as `git_mutex_lock`
        /// does.
        ///
        /// Taking it again on a thread that holds it deadlocks or panics, as it deadlocks
        /// in C.
        ///
        /// # Errors
        ///
        /// When a thread panicked while holding the lock, the lock is poisoned: it is still
        /// taken, and the [`PoisonError`] holds the guard
        /// ([`into_inner`](PoisonError::into_inner)).
        ///
        /// Replaces `mac::git_mutex_lock`
        #[doc(alias = "git_mutex_lock")]
        pub fn lock(&self) -> LockResult<MutexGuard<'_, T>> {
            match self.inner.lock() {
                Ok(inner) => Ok(MutexGuard { inner }),
                Err(poisoned) => Err(PoisonError::new(MutexGuard {
                    inner: poisoned.into_inner(),
                })),
            }
        }

        /// Whether a thread panicked while holding the lock.
        #[must_use]
        pub fn is_poisoned(&self) -> bool {
            self.inner.is_poisoned()
        }

        /// The data, through the exclusive borrow of the lock, which needs no locking.
        ///
        /// # Errors
        ///
        /// When the lock is poisoned, the [`PoisonError`] holds the data.
        pub fn get_mut(&mut self) -> LockResult<&mut T> {
            self.inner.get_mut()
        }
    }

    impl<T: ?Sized> Drop for Mutex<T> {
        /// Destroys the lock, as `git_mutex_free` does: the borrow checker sees that no
        /// guard holds it, which POSIX asks of `pthread_mutex_destroy`'s caller.
        ///
        /// Replaces `mac::git_mutex_free`
        #[doc(alias = "git_mutex_free")]
        fn drop(&mut self) {}
    }

    impl<T: Default> Default for Mutex<T> {
        fn default() -> Mutex<T> {
            Mutex::new(T::default())
        }
    }

    impl<T> From<T> for Mutex<T> {
        fn from(value: T) -> Mutex<T> {
            Mutex::new(value)
        }
    }

    impl<T: ?Sized + fmt::Debug> fmt::Debug for Mutex<T> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            fmt::Debug::fmt(&self.inner, f)
        }
    }

    impl<T: ?Sized> MutexGuard<'_, T> {
        /// Releases the lock, as `git_mutex_unlock` does; dropping the guard does the same.
        /// An associated function, `MutexGuard::unlock(guard)`, so that it hides no method
        /// of the data.
        ///
        /// Replaces `mac::git_mutex_unlock`
        #[doc(alias = "git_mutex_unlock")]
        pub fn unlock(guard: Self) {
            drop(guard);
        }
    }

    impl<T: ?Sized> Deref for MutexGuard<'_, T> {
        type Target = T;

        fn deref(&self) -> &T {
            &self.inner
        }
    }

    impl<T: ?Sized> DerefMut for MutexGuard<'_, T> {
        fn deref_mut(&mut self) -> &mut T {
            &mut self.inner
        }
    }

    impl<T: ?Sized + fmt::Debug> fmt::Debug for MutexGuard<'_, T> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            fmt::Debug::fmt(&*self.inner, f)
