    /// ```
    /// use std::sync::Arc;
    ///
    /// use libgit2_crustify::libgit2::src::util::thread::{Condvar, Mutex, spawn};
    ///
    /// let shared = Arc::new((Mutex::new(false), Condvar::new()));
    /// let theirs = Arc::clone(&shared);
    /// let thread = spawn(move || {
    ///     *theirs.0.lock().unwrap() = true;
    ///     theirs.1.notify_one();
