        ///
        /// Replaces `mac::git_rwlock_wrunlock`
        #[doc(alias = "git_rwlock_wrunlock")]
        pub fn unlock(guard: Self) {
            drop(guard);
        }
    }

    impl<T: ?Sized> Deref for RwLockWriteGuard<'_, T> {
        type Target = T;

        fn deref(&self) -> &T {
            &self.inner
        }
    }

