        .map(|_| {
            let (lock, barrier) = (Arc::clone(&lock), Arc::clone(&barrier));
            spawn(move || {
                let guard = lock.read().unwrap();
                barrier.wait();
                let seen = *guard;
                RwLockReadGuard::unlock(guard);
                seen
            })
            .unwrap()
        })
        .collect();
    for thread in threads {
        assert_eq!(thread.join().unwrap(), 7);
    }
    assert_eq!(*lock.write().unwrap(), 7);
}

