/// guard; a reader that panics does not.
#[test]
fn a_panicking_writer_poisons_an_rwlock() {
    let lock = Arc::new(RwLock::new(1));
    let theirs = Arc::clone(&lock);
    assert!(
        spawn(move || {
            let _reading = theirs.read().unwrap();
